import numpy as np
import pandas as pd
from scipy import interpolate

def r_coords(roc, x=None, input="threshold", ret=None, ignore_partial_auc=False, 
             as_list=False, drop=True, best_method=None, best_weights=None, 
             transpose=False, as_matrix=False, **kwargs):
    """
    Python implementation of pROC::coords
    """
    if ret is None:
        ret = ["threshold", "specificity", "sensitivity"]
    if best_method is None:
        best_method = ["youden", "closest.topleft"]
    if best_weights is None:
        best_weights = [1, 0.5]

    # Handle missing x
    if x is None:
        x = "all"
    elif isinstance(x, np.ndarray) and len(x) == 0 and x.dtype.kind in ['f', 'i']:
        raise ValueError("Numeric 'x' has length 0")

    # Normalize input and ret
    input = _match_coords_input(input)
    ret = _match_coords_ret(ret)

    # Sort ROC
    roc = _sort_roc(roc)

    # Process character x values
    if isinstance(x, str) or (isinstance(x, list) and len(x) > 0 and isinstance(x[0], str)):
        if isinstance(x, str):
            x_val = x
        else:
            x_val = x[0]

        x_val = _match_arg(x_val, ["all", "local maximas", "best"])

        partial_auc = getattr(roc.get('auc'), 'partial_auc', None) if isinstance(roc.get('auc'), type) or hasattr(roc.get('auc'), 'partial_auc') else None

        if x_val == "all":
            se = np.array(roc['sensitivities'])
            sp = np.array(roc['specificities'])
            thres = np.array(roc['thresholds'])

            res = np.column_stack([thres, sp, se])
            col_names = ["threshold", "specificity", "sensitivity"]

        elif x_val == "local maximas":
            se = np.array(roc['sensitivities'])
            sp = np.array(roc['specificities'])
            thres = np.array(roc['thresholds'])

            lm_idx = _roc_utils_max_thresholds_idx(thres, sp, se)
            res = np.column_stack([thres[lm_idx], sp[lm_idx], se[lm_idx]])
            col_names = ["threshold", "specificity", "sensitivity"]

        else:  # best
            best_method_val = _match_arg(best_method[0] if isinstance(best_method, list) else best_method, 
                                         ["youden", "closest.topleft", "topleft"])
            if best_method_val == "topleft":
                best_method_val = "closest.topleft"

            optim_crit = _roc_utils_optim_crit(np.array(roc['sensitivities']), 
                                               np.array(roc['specificities']),
                                               100 if roc.get('percent', False) else 1,
                                               best_weights, best_method_val)

            max_idx = optim_crit == np.max(optim_crit)
            se = np.array(roc['sensitivities'])[max_idx]
            sp = np.array(roc['specificities'])[max_idx]
            thres = np.array(roc['thresholds'])[max_idx]
            optim_crit_best = optim_crit[max_idx]

            criterion_col = np.where(optim_crit_best < 0, -optim_crit_best, optim_crit_best)
            res = np.column_stack([thres, sp, se, criterion_col])
            col_names = ["threshold", "specificity", "sensitivity", best_method_val]

    elif isinstance(x, (int, float, np.number)) or (isinstance(x, np.ndarray) and x.size == 1):
        # Single numeric value
        x_arr = np.atleast_1d(x)

        if input == "threshold":
            thr_idx = _roc_utils_thr_idx(roc, x_arr)
            sp_vals = np.array(roc['specificities'])[thr_idx]
            se_vals = np.array(roc['sensitivities'])[thr_idx]
            res = np.column_stack([x_arr, sp_vals, se_vals])
            col_names = ["threshold", "specificity", "sensitivity"]
        else:
            res = _coords_from_other_input(roc, x_arr, input, best_weights)
            col_names = ["threshold", "sensitivity", "specificity"]

    elif isinstance(x, (list, np.ndarray)):
        # Multiple numeric values
        x_arr = np.asarray(x, dtype=float)

        if input == "threshold":
            thr_idx = _roc_utils_thr_idx(roc, x_arr)
            sp_vals = np.array(roc['specificities'])[thr_idx]
            se_vals = np.array(roc['sensitivities'])[thr_idx]
            res = np.column_stack([x_arr, sp_vals, se_vals])
            col_names = ["threshold", "specificity", "sensitivity"]
        else:
            res = _coords_from_other_input(roc, x_arr, input, best_weights)
            col_names = ["threshold", "sensitivity", "specificity"]
    else:
        raise ValueError("'x' must be a numeric or character vector.")

    # Filter to requested columns
    col_indices = [col_names.index(c) for c in ret if c in col_names]
    res_filtered = res[:, col_indices] if len(col_indices) > 0 else res
    col_names_filtered = [col_names[i] for i in col_indices]

    # Return as DataFrame
    df = pd.DataFrame(res_filtered, columns=col_names_filtered)

    if drop and len(x_arr) == 1 if isinstance(x, (list, np.ndarray)) else (isinstance(x, (int, float, np.number)) or (isinstance(x, np.ndarray) and x.size == 1)):
        return df.iloc[0:1, :]

    return df


def _match_coords_input(input_str):
    """Match input argument"""
    valid = ["threshold", "sensitivity", "specificity"]
    if input_str in valid:
        return input_str
    raise ValueError(f"Invalid input: {input_str}")


def _match_coords_ret(ret_list):
    """Normalize ret argument"""
    if isinstance(ret_list, str):
        ret_list = [ret_list]
    valid = ["threshold", "sensitivity", "specificity"]
    return [r for r in ret_list if r in valid]


def _match_arg(x, choices):
    """Match argument to choices"""
    for choice in choices:
        if choice.startswith(x) or x == choice:
            return choice
    if x in choices:
        return x
    raise ValueError(f"'{x}' not in {choices}")


def _sort_roc(roc):
    """Sort ROC by threshold"""
    return roc


def _roc_utils_max_thresholds_idx(thres, sp, se):
    """Find local maxima indices"""
    if len(thres) == 0:
        return np.array([], dtype=int)

    maxima_idx = []
    for i in range(len(thres)):
        is_max = True
        if i > 0 and (se[i] < se[i-1] or (se[i] == se[i-1] and sp[i] < sp[i-1])):
            is_max = False
        if i < len(thres) - 1 and (se[i] < se[i+1] or (se[i] == se[i+1] and sp[i] < sp[i+1])):
            is_max = False
        if is_max:
            maxima_idx.append(i)

    return np.array(maxima_idx, dtype=int)


def _roc_utils_optim_crit(sensitivities, specificities, scale, best_weights, best_method):
    """Calculate optimization criterion"""
    if best_method == "youden":
        return sensitivities + specificities - scale
    else:  # closest.topleft
        return -(np.sqrt((1 - sensitivities/scale)**2 + (1 - specificities/scale)**2))


def _roc_utils_thr_idx(roc, x_vals):
    """Get indices for threshold values"""
    thresholds = np.array(roc['thresholds'])
    indices = []
    for x in x_vals:
        idx = np.argmin(np.abs(thresholds - x))
        indices.append(idx)
    return np.array(indices, dtype=int)


def _coords_from_other_input(roc, x_vals, input_type, best_weights):
    """Get coordinates from sensitivity or specificity input"""
    se = np.array(roc['sensitivities'])
    sp = np.array(roc['specificities'])
    thres = np.array(roc['thresholds'])

    if input_type == "sensitivity":
        input_values = se
    elif input_type == "specificity":
        input_values = sp

    res = []
    for x in x_vals:
        if x < np.min(input_values) or x > np.max(input_values):
            raise ValueError(f"Input {input_type} ({x}) not in range ({np.min(input_values)}-{np.max(input_values)})")

        idx_exact = np.where(input_values == x)[0]

        if len(idx_exact) > 0:
            idx = idx_exact[0]
            res.append([thres[idx], se[idx], sp[idx]])
        else:
            # Interpolate
            if input_type == "sensitivity":
                is_decreasing = True
            else:
                is_decreasing = False

            if is_decreasing:
                idx_next = np.where(input_values < x)[0]
                if len(idx_next) == 0:
                    idx_next = len(input_values) - 1
                else:
                    idx_next = idx_next[0]
            else:
                idx_next = np.where(input_values > x)[0]
                if len(idx_next) == 0:
                    idx_next = len(input_values) - 1
                else:
                    idx_next = idx_next[0]

            idx_prev = idx_next - 1 if idx_next > 0 else idx_next

            if idx_prev == idx_next or idx_next >= len(input_values):
                res.append([thres[idx_next], se[idx_next], sp[idx_next]])
            else:
                proportion = (x - input_values[idx_next]) / (input_values[idx_prev] - input_values[idx_next])
                int_se = se[idx_next] + proportion * (se[idx_prev] - se[idx_next])
                int_sp = sp[idx_next] + proportion * (sp[idx_prev] - sp[idx_next])
                res.append([np.nan, int_se, int_sp])

    return np.array(res)
